//! TLS (task X1) over real sockets: a client and a server, each with its certificate, the mutual
//! authentication of clause 6.4.3, the revocation of clause 6.4.4.4, the expiry of clause 6.4.4.5, and the
//! versions of clause 10. The material is in `tests/fixtures/tls` (generated by its `generate.sh`).

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]

use std::sync::Arc;
use std::time::Duration;

use igs_iso9506_mms::client::in_scope_capabilities;
use igs_iso9506_mms::tls::{
    revocation_from_pem, Identity as TlsIdentity, RustlsBackend, Secure, SecureConnector, TlsError,
    TlsSettings, TrustAnchors,
};
use igs_iso9506_mms::vmd::{Identity, MemoryVariable, Name, Target, Vmd};
use igs_iso9506_mms::{
    Client, ClientConfig, Connector, Error, Events, Reconnect, Server, ServerConfig,
};
use igs_iso9506_mms_codec::generated::types::{AccessResult, Data, TypeDescription, Unsigned8};
use igs_iso9506_mms_link::config::LinkConfig;
use rustls::pki_types::pem::PemObject;
use rustls::pki_types::{CertificateDer, PrivateKeyDer, ServerName};
use rustls::version::TLS12;
use tokio::net::TcpStream;
use tokio::time::timeout;

const ROOT: &[u8] = include_bytes!("fixtures/tls/root.pem");
const CRL: &[u8] = include_bytes!("fixtures/tls/crl.pem");
const SERVER: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/server.pem"),
    include_bytes!("fixtures/tls/server.key"),
);
const CLIENT: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/client.pem"),
    include_bytes!("fixtures/tls/client.key"),
);
const ROGUE: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/rogue.pem"),
    include_bytes!("fixtures/tls/rogue.key"),
);
const EXPIRED: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/expired.pem"),
    include_bytes!("fixtures/tls/expired.key"),
);
const REVOKED: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/revoked.pem"),
    include_bytes!("fixtures/tls/revoked.key"),
);

const ANSWER: Duration = Duration::from_secs(10);

/// The settings of one endpoint: its certificate (if any), the test root, and the CRL.
fn settings(identity: Option<(&[u8], &[u8])>) -> TlsSettings {
    let identity =
        identity.map(|(certificate, key)| TlsIdentity::from_pem(certificate, key).unwrap());
    TlsSettings::new(identity, TrustAnchors::from_pem(ROOT).unwrap())
        .with_revocation(revocation_from_pem(CRL).unwrap())
}

fn station(identity: Option<(&[u8], &[u8])>) -> Secure {
    Secure::new(RustlsBackend::new(&settings(identity)).unwrap())
}

fn model() -> Vmd {
    let mut vmd = Vmd::new(Identity {
        vendor: "igs".to_string(),
        model: "tls".to_string(),
        revision: "1".to_string(),
    });
    vmd.add_variable(
        &Target::vmd(Name::new("speed").unwrap()),
        Box::new(
            MemoryVariable::new(
                TypeDescription::Integer(Unsigned8(32)),
                Data::Integer(5),
                true,
            )
            .unwrap(),
        ),
    )
    .unwrap();
    vmd
}

async fn serving(server_identity: (&[u8], &[u8])) -> Server {
    let config = ServerConfig::new(LinkConfig::default()).with_tls(station(Some(server_identity)));
    Server::bind("127.0.0.1:0", config, model()).await.unwrap()
}

fn client_config() -> ClientConfig {
    ClientConfig {
        reconnect: Reconnect::Never,
        ..ClientConfig::new(LinkConfig::default(), in_scope_capabilities())
    }
}

/// A client over TLS to the server, with its station's secure backend and the name of the server.
async fn tls_client(
    server: &Server,
    identity: Option<(&[u8], &[u8])>,
    host: &str,
) -> Result<(Client, Events), Error> {
    let connector = SecureConnector::new(
        server.local_address().to_string(),
        host,
        station(identity),
        ANSWER,
    );
    timeout(ANSWER, Client::connect_with(connector, client_config()))
        .await
        .expect("the association is answered in time")
}

#[tokio::test]
async fn the_client_and_the_server_negotiate_tls_13_and_run_mms_over_it() {
    let server = serving(SERVER).await;
    // The TLS version of the connection, from the secured stream itself.
    let mut connector = SecureConnector::new(
        server.local_address().to_string(),
        "localhost",
        station(Some(CLIENT)),
        ANSWER,
    );
    let stream = connector.connect().await.unwrap();
    assert_eq!(stream.protocol_version(), Some("TLSv1.3"));
    drop(stream);

    let (client, _events) = tls_client(&server, Some(CLIENT), "localhost")
        .await
        .unwrap();
    let identity = client.identify().await.unwrap();
    assert_eq!(identity.vendor_name.0, "igs");
    let read = client
        .read(igs_iso9506_mms_codec::generated::types::ReadRequest {
            specification_with_result: None,
            variable_access_specification:
                igs_iso9506_mms_codec::generated::types::VariableAccessSpecification::ListOfVariable(vec![
                    igs_iso9506_mms_codec::generated::types::VariableAccessSpecificationListOfVariableItem {
                        variable_specification:
                            igs_iso9506_mms_codec::generated::types::VariableSpecification::Name(
                                igs_iso9506_mms_codec::generated::types::ObjectName::VmdSpecific(
                                    igs_iso9506_mms_codec::generated::types::Identifier("speed".to_string()),
                                ),
                            ),
                        alternate_access: None,
                    },
                ]),
        })
        .await
        .unwrap();
    assert_eq!(
        read.list_of_access_result,
        vec![AccessResult::Success(Data::Integer(5))]
    );
    client.close().await.unwrap();
    server.shutdown().await;
}

#[tokio::test]
async fn a_client_that_offers_only_tls_12_is_served_with_tls_12_and_its_certificate() {
    let server = serving(SERVER).await;
    let mut roots = rustls::RootCertStore::empty();
    for certificate in rustls_pemfile_certs(ROOT) {
        roots.add(certificate).unwrap();
    }
    let chain = rustls_pemfile_certs(CLIENT.0);
    let key = PrivateKeyDer::from_pem_slice(CLIENT.1).unwrap();
    let config = rustls::ClientConfig::builder_with_provider(Arc::new(
        rustls::crypto::ring::default_provider(),
    ))
    .with_protocol_versions(&[&TLS12])
    .unwrap()
    .with_root_certificates(roots)
    .with_client_auth_cert(chain, key)
    .unwrap();
    let tcp = TcpStream::connect(server.local_address()).await.unwrap();
    let connector = tokio_rustls::TlsConnector::from(Arc::new(config));
    let tls = connector
        .connect(ServerName::try_from("localhost").unwrap(), tcp)
        .await
        .unwrap();
    assert_eq!(
        tls.get_ref().1.protocol_version(),
        Some(rustls::ProtocolVersion::TLSv1_2)
    );
    drop(tls);
    server.shutdown().await;
}

fn rustls_pemfile_certs(pem: &[u8]) -> Vec<CertificateDer<'static>> {
    CertificateDer::pem_slice_iter(pem)
        .collect::<Result<Vec<_>, _>>()
        .unwrap()
}

#[tokio::test]
async fn a_client_without_a_certificate_is_refused() {
    let server = serving(SERVER).await;
    let attempt = tls_client(&server, None, "localhost").await;
    assert!(
        attempt.is_err(),
        "the server requires the client's certificate (clause 6.4.3)"
    );
    server.shutdown().await;
}

#[tokio::test]
async fn a_certificate_from_another_root_is_refused() {
    let server = serving(SERVER).await;
    let attempt = tls_client(&server, Some(ROGUE), "localhost").await;
    assert!(attempt.is_err());
    server.shutdown().await;
}

#[tokio::test]
async fn an_expired_certificate_is_refused() {
    let server = serving(SERVER).await;
    let attempt = tls_client(&server, Some(EXPIRED), "localhost").await;
    assert!(
        attempt.is_err(),
        "an expired certificate is not used (clause 6.4.4.5)"
    );
    server.shutdown().await;
}

#[tokio::test]
async fn a_revoked_certificate_is_refused_by_the_revocation_list() {
    let server = serving(SERVER).await;
    let attempt = tls_client(&server, Some(REVOKED), "localhost").await;
    assert!(
        attempt.is_err(),
        "the CRL lists the certificate (clause 6.4.4.4)"
    );
    server.shutdown().await;
}

#[tokio::test]
async fn a_server_name_outside_the_certificate_is_refused_by_the_client() {
    let server = serving(SERVER).await;
    let attempt = tls_client(&server, Some(CLIENT), "other.example").await;
    assert!(
        attempt.is_err(),
        "the server certificate does not name other.example"
    );
    server.shutdown().await;
}

#[tokio::test]
async fn a_plain_client_is_refused_by_the_tls_server() {
    let server = serving(SERVER).await;
    let attempt = timeout(
        ANSWER,
        Client::connect(&server.local_address().to_string(), client_config()),
    )
    .await
    .expect("the attempt ends in time");
    assert!(attempt.is_err());
    server.shutdown().await;
}

#[test]
fn a_backend_without_a_revocation_list_is_refused() {
    let settings = TlsSettings::new(
        Some(TlsIdentity::from_pem(CLIENT.0, CLIENT.1).unwrap()),
        TrustAnchors::from_pem(ROOT).unwrap(),
    );
    match RustlsBackend::new(&settings) {
        Err(TlsError::Invalid(message)) => assert!(message.contains("revocation"), "{message}"),
        other => panic!("the revocation check is required: {:?}", other.err()),
    }
}

#[tokio::test]
async fn a_station_without_a_certificate_of_its_own_does_not_accept() {
    // A client station has no server configuration: it refuses to act as the server of a connection.
    let backend = RustlsBackend::new(&settings(None)).unwrap();
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let dial = tokio::spawn(async move { TcpStream::connect(address).await });
    let (tcp, _) = listener.accept().await.unwrap();
    let _ = dial.await;
    let outcome = igs_iso9506_mms::tls::TlsBackend::accept(&backend, tcp).await;
    assert!(matches!(outcome, Err(TlsError::Invalid(_))));
}
